   435	    /*
   436	     * pass in the application data to the parser context.
   437	     */
   438	    pctxt->_private = ctxt->_private;
   439	
   440	    /*
   441	     * try to ensure that new documents included are actually
   442	     * built with the same dictionary as the including document.
   443	     */
