   457	    inputStream = xmlLoadExternalEntity(URL, NULL, pctxt);
   458	    if (inputStream == NULL) {
   459	        xmlFreeParserCtxt(pctxt);
   460	        return(NULL);
   461	    }
   462	
   463	    inputPush(pctxt, inputStream);
   464	
   465	    if (pctxt->directory == NULL)
   466	        pctxt->directory = xmlParserGetDirectory(URL);
   467	
